# systemd 261.2: from Phase 8a, the Wayland desktop (scripts/lfs/phase8a-inside.sh, pkg_systemd_pam).
# GENERATED by convert.py; delete this line to take the recipe over by hand.
name=systemd
version=261.2
release=1
source=(https://github.com/systemd/systemd/archive/v261.2/systemd-261.2.tar.gz)
checksums=(md5:e3f04ccc83a28ec5e80c5432bb8329f5)
depends=(cryptsetup linux-pam pefile pyelftools tpm2-tss)
imports=(systemd-crypto systemd-pam)
mode=tracked

build() {
  sed -e 's/GROUP="render"/GROUP="video"/' \
      -e 's/GROUP="sgx", //'               \
      -i rules.d/50-udev-default.rules.in
  mkdir -p build
  cd       build

  meson setup ..                \
        --prefix=/usr           \
        --buildtype=release     \
        -D default-dnssec=no    \
        -D firstboot=false      \
        -D install-tests=false  \
        -D ldconfig=false       \
        -D sysusers=true        \
        -D rpmmacrosdir=no      \
        -D homed=disabled       \
        -D man=disabled         \
        -D mode=release         \
        -D pam=enabled          \
        -D pamconfdir=/etc/pam.d \
        -D dev-kvm-mode=0660    \
        -D nobody-group=nogroup \
        -D sysupdate=disabled   \
        -D ukify=enabled        \
        -D libcryptsetup=enabled \
        -D tpm2=enabled         \
        -D bootloader=enabled   \
        -D sbat-distro=autark   \
        -D sbat-distro-summary=Autark \
        -D sbat-distro-pkgname=systemd \
        -D sbat-distro-version=261.2 \
        -D sbat-distro-url=https://github.com/Seuketchi/autark \
        -D docdir=/usr/share/doc/systemd-261.2
  ninja
  ninja install

  grep -q pam_systemd /etc/pam.d/system-session || cat >> /etc/pam.d/system-session << "EOF"
# Begin Systemd addition
session  required    pam_loginuid.so
session  optional    pam_systemd.so
# End Systemd addition
EOF
  cat > /etc/pam.d/systemd-user << "EOF"
# Begin /etc/pam.d/systemd-user
account  required    pam_access.so
account  include     system-account
session  required    pam_env.so
session  required    pam_limits.so
session  required    pam_loginuid.so
session  optional    pam_keyinit.so force revoke
session  optional    pam_systemd.so
auth     required    pam_deny.so
password required    pam_deny.so
# End /etc/pam.d/systemd-user
EOF
  install -vdm755 /etc/systemd/user-environment-generators
  cat > /etc/systemd/user-environment-generators/50-profile.sh << "EOF"
#!/usr/bin/env -S -i /usr/bin/bash
# SPDX-License-Identifier: MIT
. /etc/profile
# Systemd should have already set a better value for them.
unset XDG_RUNTIME_DIR
for i in $(locale); do
  unset ${i%=*}
done
# Some shell magic that we don't want to expose.
unset SHLVL
# Systemd does not want to pass functions to the environment
for i in $(declare -pF | awk '{print $3}'); do
  unset -f $i
done
python3 << _EOF
import os
for var in os.environ:
  # Simply unsetting them in shell does not work.
  if var in ['LC_CTYPE', '_']:
    continue
  print(var + '=' + os.environ[var])
_EOF
EOF
  chmod -v 755 /etc/systemd/user-environment-generators/50-profile.sh
}
